import { supabase } from './client'
import type { Workplace } from '@/entities/workspace/types'

/**
 * workspaces — schema (docs/schema-map.md):
 *   id, tenant_id (FK tenants.id), name, slug, description, created_by (uuid, not null),
 *   is_active, metadata. Unique (slug, tenant_id).
 */
function slugify(name: string): string {
  return name.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'workspace'
}

export const workplacesService = {
  async listWorkplaces(tenantId: string): Promise<Workplace[]> {
    const { data, error } = await supabase
      .from('workspaces')
      .select('*')
      .eq('tenant_id', tenantId)
      .is('deleted_at', null)
      .order('created_at', { ascending: false })
    if (error) throw error
    return (data ?? []) as Workplace[]
  },

  async createWorkplace(payload: {
    tenantId: string
    name: string
    description?: string | null
    createdBy: string
    slug?: string
  }): Promise<Workplace> {
    const slug = payload.slug ?? slugify(payload.name)
    const { data, error } = await supabase
      .from('workspaces')
      .insert({
        tenant_id: payload.tenantId,
        name: payload.name,
        slug,
        description: payload.description ?? null,
        created_by: payload.createdBy,
        is_active: true,
      })
      .select()
      .single()
    if (error) throw error
    return data as Workplace
  },
}
